    if (face_at_w && face_area_w == 2'd0 && face_reg_w == AW2_C'(MBX_FACE_REG_GSI_STATUS_C)) reg_rdata_w = mbx_place_f(32'(gsi_busy_r[face_if_w]), MBX_GSI_STATUS_BUSY_LSB_C, MBX_GSI_STATUS_BUSY_WIDTH_C) | mbx_place_f(32'(gsi_done_r[face_if_w]), MBX_GSI_STATUS_DONE_LSB_C, MBX_GSI_STATUS_DONE_WIDTH_C) | mbx_place_f(32'(gsi_tmo_r[face_if_w]), MBX_GSI_STATUS_TIMEOUT_LSB_C, MBX_GSI_STATUS_TIMEOUT_WIDTH_C) | mbx_place_f(32'(gsi_tag_r[face_if_w]), MBX_GSI_STATUS_TAG_LSB_C, MBX_GSI_STATUS_TAG_WIDTH_C);
    if (face_at_w && face_area_w == 2'd0 && face_reg_w == AW2_C'(MBX_FACE_REG_GSI_DATA_LO_C)) reg_rdata_w = gsi_data_r[face_if_w][32*0 +: 32];
    if (face_at_w && face_area_w == 2'd0 && face_reg_w == AW2_C'(MBX_FACE_REG_GSI_DATA_HI_C)) reg_rdata_w = gsi_data_r[face_if_w][32*1 +: 32];
    if (face_at_w && face_area_w == 2'd1 && face_reg_w == AW2_C'(MBX_FACE_SRC_REG_F_PT_OFFSET_C)) reg_rdata_w = 32'(face_f_pt_offset_r[face_if_w][face_s_w]);
    if (face_at_w && face_area_w == 2'd1 && face_reg_w == AW2_C'(MBX_FACE_SRC_REG_F_FMT_OUT_LO_C)) reg_rdata_w = 32'(face_f_fmt_out_lo_r[face_if_w][face_s_w]);
    if (face_at_w && face_area_w == 2'd1 && face_reg_w == AW2_C'(MBX_FACE_SRC_REG_F_FMT_OUT_HI_C)) reg_rdata_w = 32'(face_f_fmt_out_hi_r[face_if_w][face_s_w]);
    if (face_at_w && face_area_w == 2'd1 && face_reg_w == AW2_C'(MBX_FACE_SRC_REG_F_SRC_VALID_C)) reg_rdata_w = 32'(face_f_src_valid_r[face_if_w][face_s_w]);
    if (face_at_w && face_area_w == 2'd2 && face_reg_w == AW2_C'(MBX_FACE_SNK_REG_F_FMT_IN_LO_C)) reg_rdata_w = 32'(face_f_fmt_in_lo_r[face_if_w][face_k_w]);
    if (face_at_w && face_area_w == 2'd2 && face_reg_w == AW2_C'(MBX_FACE_SNK_REG_F_FMT_IN_HI_C)) reg_rdata_w = 32'(face_f_fmt_in_hi_r[face_if_w][face_k_w]);
    if (face_at_w && face_area_w == 2'd2 && face_reg_w == AW2_C'(MBX_FACE_SNK_REG_F_SNK_VALID_C)) reg_rdata_w = 32'(face_f_snk_valid_r[face_if_w][face_k_w]);
    for (int c = 0; c < int'(MBX_N_CH_C); c++) begin
      if (off_w == AW2_C'(MBX_CH_BASE_C + c * MBX_CH_STRIDE_C + MBX_CH_REG_RX_HEAD_C)) reg_rdata_w = mbx_place_f(32'(rx_head_w[16*c +: 16]), MBX_RX_HEAD_WORDS_LSB_C, MBX_RX_HEAD_WORDS_WIDTH_C);
      if (off_w == AW2_C'(MBX_CH_BASE_C + c * MBX_CH_STRIDE_C + MBX_CH_REG_RX_TAIL_C)) reg_rdata_w = mbx_place_f(32'(rx_tail_r[c]), MBX_RX_TAIL_WORDS_LSB_C, MBX_RX_TAIL_WORDS_WIDTH_C);
      if (off_w == AW2_C'(MBX_CH_BASE_C + c * MBX_CH_STRIDE_C + MBX_CH_REG_TX_HEAD_C)) reg_rdata_w = mbx_place_f(32'(tx_head_r[c]), MBX_TX_HEAD_WORDS_LSB_C, MBX_TX_HEAD_WORDS_WIDTH_C);
      if (off_w == AW2_C'(MBX_CH_BASE_C + c * MBX_CH_STRIDE_C + MBX_CH_REG_TX_TAIL_C)) reg_rdata_w = mbx_place_f(32'(tx_tail_w[16*c +: 16]), MBX_TX_TAIL_WORDS_LSB_C, MBX_TX_TAIL_WORDS_WIDTH_C);
      if (off_w == AW2_C'(MBX_CH_BASE_C + c * MBX_CH_STRIDE_C + MBX_CH_REG_RX_DROP_C)) reg_rdata_w = mbx_place_f(32'(rx_drop_w[16*c +: 16]), MBX_RX_DROP_COUNT_LSB_C, MBX_RX_DROP_COUNT_WIDTH_C);
      if (off_w == AW2_C'(MBX_CH_BASE_C + c * MBX_CH_STRIDE_C + MBX_CH_REG_RATE_DROP_C)) reg_rdata_w = mbx_place_f(32'(rate_drop_w[16*c +: 16]), MBX_RATE_DROP_COUNT_LSB_C, MBX_RATE_DROP_COUNT_WIDTH_C);
      if (off_w == AW2_C'(MBX_CH_BASE_C + c * MBX_CH_STRIDE_C + MBX_CH_REG_TX_ERR_C)) reg_rdata_w = mbx_place_f(32'(tx_err_w[16*c +: 16]), MBX_TX_ERR_COUNT_LSB_C, MBX_TX_ERR_COUNT_WIDTH_C);
      if (off_w == AW2_C'(MBX_CH_BASE_C + c * MBX_CH_STRIDE_C + MBX_CH_REG_RX_PASS_C)) reg_rdata_w = mbx_place_f(32'(rx_pass_w[16*c +: 16]), MBX_RX_PASS_COUNT_LSB_C, MBX_RX_PASS_COUNT_WIDTH_C);
    end
  end : reg_read

  // ---- the rings ------------------------------------------------------------------
  logic [31:0] evt_rdata_w;
  logic        evt_host_w;   //! the host reads the event ring this cycle
  assign evt_host_w = rd_w && off_w >= AW2_C'(MBX_EVT_BASE_C)
                      && off_w < AW2_C'(MBX_EVT_BASE_C + 4 * MBX_EVT_WORDS_C);
  KL_mbx_ring #(.WORDS_P(MBX_EVT_WORDS_C)) u_evt_ring (
    .clk_i     (clk_i),
    .rst_n     (rst_n),
    .wr_en_i   (evw_en_w),
    .wr_addr_i (evw_addr_w),
    .wr_data_i (evw_data_w),
    .rd_en_i   (evt_host_w),
    .rd_addr_i ($clog2(MBX_EVT_WORDS_C)'((off_w - AW2_C'(MBX_EVT_BASE_C)) >> 2)),
    .rd_data_o (evt_rdata_w)
  );

  // channel adp (0): receive ring at 0x1000
  logic [31:0] adp_rx_rdata_w;
  logic        adp_rx_host_w;   //! the host reads this ring this cycle
  assign adp_rx_host_w = rd_w && off_w >= AW2_C'(MBX_CH_ADP_RX_BASE_C)
                      && off_w < AW2_C'(MBX_CH_ADP_RX_BASE_C + 4 * MBX_CH_ADP_RX_WORDS_C);
  KL_mbx_ring #(.WORDS_P(MBX_CH_ADP_RX_WORDS_C)) u_adp_rx (
    .clk_i     (clk_i),
    .rst_n     (rst_n),
    .wr_en_i   (rxw_en_w && rxw_ch_w == MBX_CH_W_C'(MBX_CH_ADP_C)),
    .wr_addr_i (rxw_addr_w[$clog2(MBX_CH_ADP_RX_WORDS_C)-1:0]),
    .wr_data_i (rxw_data_w),
    .rd_en_i   (adp_rx_host_w),
    .rd_addr_i ($clog2(MBX_CH_ADP_RX_WORDS_C)'((off_w - AW2_C'(MBX_CH_ADP_RX_BASE_C)) >> 2)),
    .rd_data_o (adp_rx_rdata_w)
  );

  // channel adp (0): transmit ring at 0x1400
  logic [31:0] adp_tx_rdata_w;
  logic        adp_tx_host_w;   //! the host writes this ring this cycle
  assign adp_tx_host_w = wr_w && off_w >= AW2_C'(MBX_CH_ADP_TX_BASE_C)
                      && off_w < AW2_C'(MBX_CH_ADP_TX_BASE_C + 4 * MBX_CH_ADP_TX_WORDS_C);
  KL_mbx_ring #(.WORDS_P(MBX_CH_ADP_TX_WORDS_C)) u_adp_tx (
    .clk_i     (clk_i),
    .rst_n     (rst_n),
    .wr_en_i   (adp_tx_host_w),
    .wr_addr_i ($clog2(MBX_CH_ADP_TX_WORDS_C)'((off_w - AW2_C'(MBX_CH_ADP_TX_BASE_C)) >> 2)),
    .wr_data_i (host_wdata_i),
    .rd_en_i   (txr_en_w && txr_ch_w == MBX_CH_W_C'(MBX_CH_ADP_C)),
    .rd_addr_i (txr_addr_w[$clog2(MBX_CH_ADP_TX_WORDS_C)-1:0]),
    .rd_data_o (adp_tx_rdata_w)
  );

  // channel acmp (1): receive ring at 0x1800
  logic [31:0] acmp_rx_rdata_w;
  logic        acmp_rx_host_w;   //! the host reads this ring this cycle
  assign acmp_rx_host_w = rd_w && off_w >= AW2_C'(MBX_CH_ACMP_RX_BASE_C)
                      && off_w < AW2_C'(MBX_CH_ACMP_RX_BASE_C + 4 * MBX_CH_ACMP_RX_WORDS_C);
  KL_mbx_ring #(.WORDS_P(MBX_CH_ACMP_RX_WORDS_C)) u_acmp_rx (
    .clk_i     (clk_i),
    .rst_n     (rst_n),
    .wr_en_i   (rxw_en_w && rxw_ch_w == MBX_CH_W_C'(MBX_CH_ACMP_C)),
    .wr_addr_i (rxw_addr_w[$clog2(MBX_CH_ACMP_RX_WORDS_C)-1:0]),
    .wr_data_i (rxw_data_w),
    .rd_en_i   (acmp_rx_host_w),
    .rd_addr_i ($clog2(MBX_CH_ACMP_RX_WORDS_C)'((off_w - AW2_C'(MBX_CH_ACMP_RX_BASE_C)) >> 2)),
    .rd_data_o (acmp_rx_rdata_w)
  );

  // channel acmp (1): transmit ring at 0x1C00
  logic [31:0] acmp_tx_rdata_w;
  logic        acmp_tx_host_w;   //! the host writes this ring this cycle
  assign acmp_tx_host_w = wr_w && off_w >= AW2_C'(MBX_CH_ACMP_TX_BASE_C)
                      && off_w < AW2_C'(MBX_CH_ACMP_TX_BASE_C + 4 * MBX_CH_ACMP_TX_WORDS_C);
  KL_mbx_ring #(.WORDS_P(MBX_CH_ACMP_TX_WORDS_C)) u_acmp_tx (
    .clk_i     (clk_i),
    .rst_n     (rst_n),
    .wr_en_i   (acmp_tx_host_w),
    .wr_addr_i ($clog2(MBX_CH_ACMP_TX_WORDS_C)'((off_w - AW2_C'(MBX_CH_ACMP_TX_BASE_C)) >> 2)),
    .wr_data_i (host_wdata_i),
    .rd_en_i   (txr_en_w && txr_ch_w == MBX_CH_W_C'(MBX_CH_ACMP_C)),
    .rd_addr_i (txr_addr_w[$clog2(MBX_CH_ACMP_TX_WORDS_C)-1:0]),
    .rd_data_o (acmp_tx_rdata_w)
  );

  // channel aecp (2): receive ring at 0x2000
  logic [31:0] aecp_rx_rdata_w;
  logic        aecp_rx_host_w;   //! the host reads this ring this cycle
  assign aecp_rx_host_w = rd_w && off_w >= AW2_C'(MBX_CH_AECP_RX_BASE_C)
                      && off_w < AW2_C'(MBX_CH_AECP_RX_BASE_C + 4 * MBX_CH_AECP_RX_WORDS_C);
  KL_mbx_ring #(.WORDS_P(MBX_CH_AECP_RX_WORDS_C)) u_aecp_rx (
    .clk_i     (clk_i),
    .rst_n     (rst_n),
    .wr_en_i   (rxw_en_w && rxw_ch_w == MBX_CH_W_C'(MBX_CH_AECP_C)),
    .wr_addr_i (rxw_addr_w[$clog2(MBX_CH_AECP_RX_WORDS_C)-1:0]),
    .wr_data_i (rxw_data_w),
    .rd_en_i   (aecp_rx_host_w),
    .rd_addr_i ($clog2(MBX_CH_AECP_RX_WORDS_C)'((off_w - AW2_C'(MBX_CH_AECP_RX_BASE_C)) >> 2)),
    .rd_data_o (aecp_rx_rdata_w)
  );

  // channel aecp (2): transmit ring at 0x2800
  logic [31:0] aecp_tx_rdata_w;
  logic        aecp_tx_host_w;   //! the host writes this ring this cycle
  assign aecp_tx_host_w = wr_w && off_w >= AW2_C'(MBX_CH_AECP_TX_BASE_C)
                      && off_w < AW2_C'(MBX_CH_AECP_TX_BASE_C + 4 * MBX_CH_AECP_TX_WORDS_C);
  KL_mbx_ring #(.WORDS_P(MBX_CH_AECP_TX_WORDS_C)) u_aecp_tx (
    .clk_i     (clk_i),
    .rst_n     (rst_n),
    .wr_en_i   (aecp_tx_host_w),
    .wr_addr_i ($clog2(MBX_CH_AECP_TX_WORDS_C)'((off_w - AW2_C'(MBX_CH_AECP_TX_BASE_C)) >> 2)),
    .wr_data_i (host_wdata_i),
    .rd_en_i   (txr_en_w && txr_ch_w == MBX_CH_W_C'(MBX_CH_AECP_C)),
    .rd_addr_i (txr_addr_w[$clog2(MBX_CH_AECP_TX_WORDS_C)-1:0]),
    .rd_data_o (aecp_tx_rdata_w)
  );

  // channel maap (3): receive ring at 0x3000
  logic [31:0] maap_rx_rdata_w;
  logic        maap_rx_host_w;   //! the host reads this ring this cycle
  assign maap_rx_host_w = rd_w && off_w >= AW2_C'(MBX_CH_MAAP_RX_BASE_C)
                      && off_w < AW2_C'(MBX_CH_MAAP_RX_BASE_C + 4 * MBX_CH_MAAP_RX_WORDS_C);
  KL_mbx_ring #(.WORDS_P(MBX_CH_MAAP_RX_WORDS_C)) u_maap_rx (
    .clk_i     (clk_i),
    .rst_n     (rst_n),
    .wr_en_i   (rxw_en_w && rxw_ch_w == MBX_CH_W_C'(MBX_CH_MAAP_C)),
    .wr_addr_i (rxw_addr_w[$clog2(MBX_CH_MAAP_RX_WORDS_C)-1:0]),
    .wr_data_i (rxw_data_w),
    .rd_en_i   (maap_rx_host_w),
    .rd_addr_i ($clog2(MBX_CH_MAAP_RX_WORDS_C)'((off_w - AW2_C'(MBX_CH_MAAP_RX_BASE_C)) >> 2)),
    .rd_data_o (maap_rx_rdata_w)
  );

  // channel maap (3): transmit ring at 0x3200
  logic [31:0] maap_tx_rdata_w;
  logic        maap_tx_host_w;   //! the host writes this ring this cycle
  assign maap_tx_host_w = wr_w && off_w >= AW2_C'(MBX_CH_MAAP_TX_BASE_C)
                      && off_w < AW2_C'(MBX_CH_MAAP_TX_BASE_C + 4 * MBX_CH_MAAP_TX_WORDS_C);
  KL_mbx_ring #(.WORDS_P(MBX_CH_MAAP_TX_WORDS_C)) u_maap_tx (
    .clk_i     (clk_i),
    .rst_n     (rst_n),
    .wr_en_i   (maap_tx_host_w),
    .wr_addr_i ($clog2(MBX_CH_MAAP_TX_WORDS_C)'((off_w - AW2_C'(MBX_CH_MAAP_TX_BASE_C)) >> 2)),
    .wr_data_i (host_wdata_i),
    .rd_en_i   (txr_en_w && txr_ch_w == MBX_CH_W_C'(MBX_CH_MAAP_C)),
    .rd_addr_i (txr_addr_w[$clog2(MBX_CH_MAAP_TX_WORDS_C)-1:0]),
    .rd_data_o (maap_tx_rdata_w)
  );

  // channel srp (4): receive ring at 0x4000
  logic [31:0] srp_rx_rdata_w;
  logic        srp_rx_host_w;   //! the host reads this ring this cycle
  assign srp_rx_host_w = rd_w && off_w >= AW2_C'(MBX_CH_SRP_RX_BASE_C)
                      && off_w < AW2_C'(MBX_CH_SRP_RX_BASE_C + 4 * MBX_CH_SRP_RX_WORDS_C);
  KL_mbx_ring #(.WORDS_P(MBX_CH_SRP_RX_WORDS_C)) u_srp_rx (
    .clk_i     (clk_i),
    .rst_n     (rst_n),
    .wr_en_i   (rxw_en_w && rxw_ch_w == MBX_CH_W_C'(MBX_CH_SRP_C)),
    .wr_addr_i (rxw_addr_w[$clog2(MBX_CH_SRP_RX_WORDS_C)-1:0]),
    .wr_data_i (rxw_data_w),
    .rd_en_i   (srp_rx_host_w),
    .rd_addr_i ($clog2(MBX_CH_SRP_RX_WORDS_C)'((off_w - AW2_C'(MBX_CH_SRP_RX_BASE_C)) >> 2)),
    .rd_data_o (srp_rx_rdata_w)
  );

  // channel srp (4): transmit ring at 0x5000
  logic [31:0] srp_tx_rdata_w;
  logic        srp_tx_host_w;   //! the host writes this ring this cycle
  assign srp_tx_host_w = wr_w && off_w >= AW2_C'(MBX_CH_SRP_TX_BASE_C)
                      && off_w < AW2_C'(MBX_CH_SRP_TX_BASE_C + 4 * MBX_CH_SRP_TX_WORDS_C);
  KL_mbx_ring #(.WORDS_P(MBX_CH_SRP_TX_WORDS_C)) u_srp_tx (
    .clk_i     (clk_i),
    .rst_n     (rst_n),
    .wr_en_i   (srp_tx_host_w),
    .wr_addr_i ($clog2(MBX_CH_SRP_TX_WORDS_C)'((off_w - AW2_C'(MBX_CH_SRP_TX_BASE_C)) >> 2)),
    .wr_data_i (host_wdata_i),
    .rd_en_i   (txr_en_w && txr_ch_w == MBX_CH_W_C'(MBX_CH_SRP_C)),
    .rd_addr_i (txr_addr_w[$clog2(MBX_CH_SRP_TX_WORDS_C)-1:0]),
    .rd_data_o (srp_tx_rdata_w)
  );

  // ---- the answer, one cycle after the request ---------------------------------
  logic        ack_r;
  logic [31:0] reg_rdata_r;
  logic [3:0]  rsel_r;     //! 0 a register, 1 the event ring, 2 + c channel c's receive ring
  logic [MBX_CH_W_C-1:0] txr_ch_r;   //! the transmit ring the merge read last cycle
  always_ff @(posedge clk_i) begin : answer
    if (!rst_n) begin
      ack_r       <= 1'b0;
      reg_rdata_r <= '0;
      rsel_r      <= '0;
      txr_ch_r    <= '0;
    end else begin
      ack_r       <= host_req_i;
      reg_rdata_r <= reg_rdata_w;
      txr_ch_r    <= txr_ch_w;
      rsel_r      <= evt_host_w ? 4'd1
                   : adp_rx_host_w ? 4'd2
                   : acmp_rx_host_w ? 4'd3
                   : aecp_rx_host_w ? 4'd4
                   : maap_rx_host_w ? 4'd5
                   : srp_rx_host_w ? 4'd6
                   : 4'd0;
    end
  end : answer

  assign host_ack_o = ack_r;
  always_comb begin : answer_mux
    unique case (rsel_r)
      4'd1:    host_rdata_o = evt_rdata_w;
      4'd2:    host_rdata_o = adp_rx_rdata_w;
      4'd3:    host_rdata_o = acmp_rx_rdata_w;
      4'd4:    host_rdata_o = aecp_rx_rdata_w;
      4'd5:    host_rdata_o = maap_rx_rdata_w;
      4'd6:    host_rdata_o = srp_rx_rdata_w;
      default: host_rdata_o = reg_rdata_r;
    endcase
  end : answer_mux

  logic [31:0] txr_data_w;   //! the transmit ring word the merge asked for last cycle
  always_comb begin : tx_return
    unique case (txr_ch_r)
      MBX_CH_W_C'(MBX_CH_ADP_C): txr_data_w = adp_tx_rdata_w;
      MBX_CH_W_C'(MBX_CH_ACMP_C): txr_data_w = acmp_tx_rdata_w;
      MBX_CH_W_C'(MBX_CH_AECP_C): txr_data_w = aecp_tx_rdata_w;
      MBX_CH_W_C'(MBX_CH_MAAP_C): txr_data_w = maap_tx_rdata_w;
      MBX_CH_W_C'(MBX_CH_SRP_C): txr_data_w = srp_tx_rdata_w;
      default: txr_data_w = '0;
    endcase
  end : tx_return

  always_comb begin : pending
    for (int c = 0; c < int'(MBX_N_CH_C); c++) begin
      rx_tail_w[16*c +: 16] = rx_tail_r[c];
      tx_head_w[16*c +: 16] = tx_head_r[c];
      rx_pending_w[c]       = rx_head_w[16*c +: 16] != rx_tail_r[c];
    end
    evt_pending_w = evt_head_w != evt_tail_r[15:0];
    for (int i = 0; i < int'(MBX_N_IF_C); i++) begin
      own_mac_w[48*i +: 48] = {own_mac_hi_r[i], own_mac_lo_r[i]};
    end
  end : pending

  logic irq_r;
  always_ff @(posedge clk_i) begin : interrupt
    if (!rst_n) irq_r <= 1'b0;
    else irq_r <= |((mbx_place_f(32'(rx_pending_w), MBX_IRQ_STATUS_RX_LSB_C, MBX_IRQ_STATUS_RX_WIDTH_C) | mbx_place_f(32'(evt_pending_w), MBX_IRQ_STATUS_EVT_LSB_C, MBX_IRQ_STATUS_EVT_WIDTH_C) | mbx_place_f(32'(err_r), MBX_IRQ_STATUS_ERR_LSB_C, MBX_IRQ_STATUS_ERR_WIDTH_C)) & irq_enable_r);
  end : interrupt
  assign irq_o = irq_r;

  KL_mbx_rx u_rx (
    .clk_i           (clk_i),
    .rst_n           (rst_n),
    .ms_tick_p_i     (ms_tick_p_i),
    .now_ms_i        (now_ms_r),
    .own_eid_i       ({own_eid_hi_r, own_eid_lo_r}),
    .own_mac_i       (own_mac_w),
    .bnd_req_i       (host_req_i && bnd_at_w),
    .bnd_we_i        (wr_w && bnd_at_w),
    .bnd_if_i        (bnd_if_w),
    .bnd_entry_i     (bnd_entry_w),
    .bnd_reg_i       (bnd_reg_w),
    .bnd_wdata_i     (host_wdata_i),
    .bnd_eid_o       (bnd_eid_w),
    .bnd_eid_vld_o   (bnd_eid_vld_w),
    .bnd_en_o        (bnd_en_w),
    .open_i          (filter_en_r[MBX_N_CH_C-1:0]),
    .maap_base_i     ({maap_base_hi_r[15:0], maap_base_lo_r}),
    .maap_count_i    (maap_count_r[15:0]),
    .rx_valid_i      (rx_valid_i),
    .rx_ready_o      (rx_ready_o),
    .rx_data_i       (rx_data_i),
    .rx_last_i       (rx_last_i),
    .rx_if_i         (rx_if_i),
    .wr_en_o         (rxw_en_w),
    .wr_ch_o         (rxw_ch_w),
    .wr_addr_o       (rxw_addr_w),
    .wr_data_o       (rxw_data_w),
    .rx_tail_words_i (rx_tail_w),
    .rx_head_words_o (rx_head_w),
    .rx_drop_cnt_o   (rx_drop_w),
    .rate_drop_cnt_o (rate_drop_w),
    .rx_pass_cnt_o   (rx_pass_w),
    .mismatch_cnt_o  (filter_mismatch_w),
    .err_p_o         (rx_err_p_w)
  );

  KL_mbx_tx u_tx (
    .clk_i           (clk_i),
    .rst_n           (rst_n),
    .tx_head_words_i (tx_head_w),
    .tx_tail_words_o (tx_tail_w),
    .tx_err_cnt_o    (tx_err_w),
    .err_p_o         (tx_err_p_w),
    .rd_en_o         (txr_en_w),
    .rd_ch_o         (txr_ch_w),
    .rd_addr_o       (txr_addr_w),
    .rd_data_i       (txr_data_w),
    .tx_valid_o      (tx_valid_o),
    .tx_ready_i      (tx_ready_i),
    .tx_data_o       (tx_data_o),
    .tx_last_o       (tx_last_o),
    .tx_if_o         (tx_if_o),
    .tx_ch_o         (tx_ch_o)
  );

  KL_mbx_evt u_evt (
    .clk_i             (clk_i),
    .rst_n             (rst_n),
    .ms_tick_p_i       (ms_tick_p_i),
    .now_ms_i          (now_ms_r),
    .tick_en_i         (tick_ctl_r[MBX_TICK_CTL_EN_LSB_C]),
    .tmr_cmd_p_i       (tmr_cmd_p_w),
    .tmr_slot_i        (8'(mbx_field_f(host_wdata_i, MBX_TMR_CMD_SLOT_LSB_C, MBX_TMR_CMD_SLOT_WIDTH_C))),
    .tmr_tag_i         (16'(mbx_field_f(host_wdata_i, MBX_TMR_CMD_TAG_LSB_C, MBX_TMR_CMD_TAG_WIDTH_C))),
    .tmr_op_i          (2'(mbx_field_f(host_wdata_i, MBX_TMR_CMD_OP_LSB_C, MBX_TMR_CMD_OP_WIDTH_C))),
    .tmr_deadline_ms_i (tmr_deadline_r),
    .tmr_bad_p_o       (tmr_bad_p_w),
    .link_up_i         (link_up_i),
    .gm_change_p_i     (gm_change_p_i),
    .gm_id_i           (gm_id_i),
    .gptp_domain_i     (gptp_domain_i),
    .ctr_chg_p_i       (ctr_chg_p_i),
    .ctr_chg_type_i    (ctr_chg_type_i),
    .ctr_chg_index_i   (ctr_chg_index_i),
    .avb_chg_p_i       (avb_chg_p_i),
    .asp_chg_p_i       (asp_chg_p_i),
    .amap_wr_p_i       (amap_wr_p_i),
    .evt_tail_words_i  (evt_tail_r[15:0]),
    .evt_head_words_o  (evt_head_w),
    .wr_en_o           (evw_en_w),
    .wr_addr_o         (evw_addr_w),
    .wr_data_o         (evw_data_w)
  );

  // the window bits a 16-bit register does not carry, the upper
  // filter-enable, MAAP and TICK_CTL bits a narrower build does not use,
  // and the ring index bits above the narrower rings of this contract
  logic unused_w;
  assign unused_w = ^{evt_tail_r[31:16], maap_base_hi_r[31:16], maap_count_r[31:16],
                      filter_en_r[31:MBX_N_CH_C], tick_ctl_r[31:1], rxw_addr_w, txr_addr_w};

endmodule : KL_mbx

